import { useState } from "react";

function ToDoList(){
	//할 일을 저장할 state 변수를 선언. 문자열. todo
	let [todo, setTodo] = useState("");

	//할 일 목록을 저장할 state 변수를 선언. 객체 배열. todos
	//id : 번호, todo : 할일
	let [todos, setTodos] = useState([
		{id : 1, todo : "할 일1"},
		{id : 2, todo : "할 일2"},
	]);

	//번호를 저장할 변수를 선언
	let num = 3;

	//할 일을 입력하면 state 변수에 저장하는 함수 선언 및 이벤트 등록
	const todoChange = e =>{
		//todo에 입력된 값을 저장
		setTodo(e.target.value);
	}

	//등록을 클릭하면 입력된 할 일을 할 일 목록에 추가하는 함수 선언 및 이벤트 등록
	const addTodo = e =>{
		e.preventDefault(); //form 태그에 submit 이벤트가 발생되어 서버에 전송되지 않게 하기 위해
		
		//setTodos([...todos, 추가할객체]);
		setTodo("");
	}

	return(
		<div>
			<form onSubmit={addTodo}>
				<input type="text" placeholder="할 일을 입력하세요." onChange={todoChange}
				value={todo}/>
				<button>등록</button>
			</form>
			<h1>할 일 목록</h1>
			<ul>
				<li>할 일1</li>
				<li>할 일2</li>
			</ul>
		</div>
	)
}
